//! Prepared and signed forms of [`L1ActionKind`].
//!
//! `L1ActionKind` itself, its conversions and its per-variant methods are generated by
//! `impl_action_kind!` in `mod.rs`, from the same `l1` list as `ActionKind`.

use alloy::{
    primitives::{Address, B256},
    signers::local::PrivateKeySigner,
};
use alloy_signer::{Signature, SignerSync};

use crate::{actions::L1ActionKind, Error};

/// An [`L1ActionKind`] with its nonce set and its signing hash computed, ready for a
/// signature. Built by [`L1ActionKind::prepare`].
#[derive(Debug, Clone)]
pub struct PreparedL1Action {
    pub action: L1ActionKind,
    pub nonce: u64,
    pub vault_address: Option<Address>,
    pub expires_after: Option<u64>,
    signing_hash: B256,
}

impl PreparedL1Action {
    pub(crate) fn new(
        action: L1ActionKind,
        nonce: u64,
        vault_address: Option<Address>,
        expires_after: Option<u64>,
        signing_hash: B256,
    ) -> Self {
        Self {
            action,
            nonce,
            vault_address,
            expires_after,
            signing_hash,
        }
    }

    /// The EIP-712 `Agent` digest to sign.
    pub fn signing_hash(&self) -> B256 {
        self.signing_hash
    }

    /// Sign with a local wallet.
    ///
    /// # Errors
    /// Returns [`Error::SignatureFailure`] if signing fails.
    pub fn sign(self, wallet: &PrivateKeySigner) -> Result<SignedL1Action, Error> {
        let signature = wallet
            .sign_hash_sync(&self.signing_hash)
            .map_err(|e| Error::SignatureFailure(e.to_string()))?;
        Ok(self.with_signature(signature))
    }

    /// Attach a signature produced elsewhere over [`PreparedL1Action::signing_hash`].
    pub fn with_signature(self, signature: Signature) -> SignedL1Action {
        SignedL1Action {
            action: self.action,
            nonce: self.nonce,
            signature,
            vault_address: self.vault_address,
            expires_after: self.expires_after,
        }
    }
}

/// A signed [`L1ActionKind`], ready to submit.
///
/// Serialises to the same `/exchange` body as [`SignedAction`](crate::SignedAction) of
/// the concrete action it holds:
/// ```json
/// {
///   "action": { "type": "actionType", ...payload... },
///   "nonce": 12345,
///   "signature": { "r": "0x...", "s": "0x...", "v": 27 },
///   "vaultAddress": "0x...",  // only when set
///   "expiresAfter": 12345     // only when set
/// }
/// ```
#[derive(Debug, Clone)]
pub struct SignedL1Action {
    pub action: L1ActionKind,
    pub nonce: u64,
    pub signature: Signature,
    pub vault_address: Option<Address>,
    pub expires_after: Option<u64>,
}
